old_string:
// Use workflow.attempt to drive the batch through email dispatch (processing → completed/failed)
const claimed = await workflow.attempt<NotificationBatchRow, void>(
  "notification_batches",
  newBatchId,
  { from: "processing" },
  async (_row) => {
    // Dispatch emails (respects quiet hours; if in quiet hours, sends are left pending for cron)
    await dispatchBatchEmails(newBatchId as NotificationBatchId, itemExternalId);
  },
);

new_string:
// Use workflow.attempt to drive the batch through email dispatch (pending → running → completed/failed)
const claimed = await workflow.attempt<NotificationBatchRow, void>(
  "notification_batches",
  newBatchId,
  { from: "pending" },
  async (_row) => {
    // Dispatch emails (respects quiet hours; if in quiet hours, sends are left pending for cron)
    await dispatchBatchEmails(newBatchId as NotificationBatchId, itemExternalId);
  },
);
